<script>
// ===== CHIP-8 EMULATOR =====
const FONTSET = [
  0xF0,0x90,0x90,0x90,0xF0, // 0
  0x60,0x40,0x40,0x40,0xF0, // 1
  0xF0,0x10,0xF0,0x80,0xF0, // 2
  0xF0,0x10,0xF0,0x10,0xF0, // 3
  0x60,0x80,0xF0,0x80,0x60, // 4
  0xF0,0x80,0xF0,0x10,0xF0, // 5
  0xF0,0x80,0xF0,0x90,0xF0, // 6
  0xF0,0x10,0x20,0x40,0x40, // 7
  0xF0,0x80,0xF0,0x80,0xF0, // 8
  0xF0,0x10,0xF0,0x10,0xF0, // 9
  0xF0,0x10,0xF0,0x10,0x10, // A
  0xF0,0x80,0xF0,0x80,0x80, // B
  0xE0,0x90,0x90,0x90,0xE0, // C
  0xF0,0x80,0x80,0x80,0xF0, // D
  0xE0,0x90,0x80,0x80,0xE0, // E
  0xF0,0x80,0xF0,0x10,0xF0  // F
];

class CHIP8 {
  constructor() { this.reset(); }

  reset() {
    this.memory = new Uint8Array(4096);
    this.V = new Uint8Array(16);
    this.I = 0;
    this.pc = 0x200;
    this.stack = [];
    this.sp = 0;
    this.delayTimer = 0;
    this.soundTimer = 0;
    this.display = new Uint8Array(64 * 32);
    this.keys = new Uint8Array(16);
    this.running = false;
    this.instructionsExecuted = 0;
    // Load font
    for (let i = 0; i < FONTSET.length; i++) {
      this.memory[0x050 + i] = FONTSET[i];
    }
  }

  loadROM(data) {
    for (let i = 0; i < data.length; i++) {
      this.memory[0x200 + i] = data[i];
    }
  }

  pushStack(addr) {
    if (this.sp >= 16) return;
    this.stack[this.sp++] = addr;
  }

  popStack() {
    if (this.sp <= 0) return 0x0200;
    return this.stack[--this.sp];
  }

  decodeInstr(op) {
    const x = (op >> 8) & 0xF;
    const y = (op >> 4) & 0xF;
    const nn = op & 0xFF;
    const nnn = op & 0xFFF;
    const n = op & 0xF;
    let mnemonic = '';
    switch(op & 0xF000) {
      case 0x0000:
        if (op === 0xE0E0) mnemonic = 'cls';
        else if (op === 0xEEEE) mnemonic = 'ret';
        else mnemonic = `sys ${nnn.toString(16).toUpperCase().padStart(3,'0')}`;
        break;
      case 0x1000: mnemonic = `jp ${nnn.toString(16).toUpperCase().padStart(3,'0')}`; break;
      case 0x2000: mnemonic = `call ${nnn.toString(16).toUpperCase().padStart(3,'0')}`; break;
      case 0x3000: mnemonic = `se V${x.toString(16)} ${nn.toString(16).toUpperCase().padStart(2,'0')}`; break;
      case 0x4000: mnemonic = `sne V${x.toString(16)} ${nn.toString(16).toUpperCase().padStart(2,'0')}`; break;
      case 0x5000: mnemonic = `se V${x.toString(16)} V${y.toString(16)}`; break;
      case 0x6000: mnemonic = `ld V${x.toString(16)}, ${nn.toString(16).toUpperCase().padStart(2,'0')}`; break;
      case 0x7000: mnemonic = `add V${x.toString(16)}, ${nn.toString(16).toUpperCase().padStart(2,'0')}`; break;
      case 0x8000:
        switch(n) {
          case 0x0: mnemonic = `ld V${x.toString(16)}, V${y.toString(16)}`; break;
          case 0x1: mnemonic = `or V${x.toString(16)}, V${y.toString(16)}`; break;
          case 0x2: mnemonic = `and V${x.toString(16)}, V${y.toString(16)}`; break;
          case 0x3: mnemonic = `xor V${x.toString(16)}, V${y.toString(16)}`; break;
          case 0x4: mnemonic = `add V${x.toString(16)}, V${y.toString(16)}`; break;
          case 0x5: mnemonic = `sub V${x.toString(16)}, V${y.toString(16)}`; break;
          case 0x6: mnemonic = `shr V${x.toString(16)}`; break;
          case 0x7: mnemonic = `subn V${x.toString(16)}, V${y.toString(16)}`; break;
          case 0xE: mnemonic = `shl V${x.toString(16)}`; break;
          default: mnemonic = `8_${n.toString(16)} ${op.toString(16).toUpperCase()}`;
        }
        break;
      case 0x9000: mnemonic = `sne V${x.toString(16)}, V${y.toString(16)}`; break;
      case 0xA000: mnemonic = `ld I, ${nnn.toString(16).toUpperCase().padStart(3,'0')}`; break;
      case 0xB000: mnemonic = `jp @V0, ${nnn.toString(16).toUpperCase().padStart(3,'0')}`; break;
      case 0xC000: { const kk = op & 0xFF; mnemonic = `rnd V${x.toString(16)}, ${kk.toString(16).toUpperCase().padStart(2,'0')}`; break; }
      case 0xD000: mnemonic = `drw V${x.toString(16)}, V${y.toString(16)}, ${n}`; break;
      case 0xE000:
        if (nn === 0x9E) mnemonic = `skp V${x.toString(16)}`;
        else if (nn === 0xA1) mnemonic = `sknp V${x.toString(16)}`;
        break;
      case 0xF000:
        switch(nn) {
          case 0x07: mnemonic = `ld V${x.toString(16)}, dt`; break;
          case 0x0A: mnemonic = `wait V${x.toString(16)}`; break;
          case 0x15: mnemonic = `ld dt, V${x.toString(16)}`; break;
          case 0x18: mnemonic = `ld st, V${x.toString(16)}`; break;
          case 0x1E: mnemonic = `add I, V${x.toString(16)}`; break;
          case 0x29: mnemonic = `ld I, sprite(V${x.toString(16)})`; break;
          case 0x33: mnemonic = `bcd V${x.toString(16)}`; break;
          case 0x55: mnemonic = `ld [I], V${x.toString(16)}`; break;
          case 0x65: mnemonic = `ld V${x.toString(16)}, [I]`; break;
          case 0x75: mnemonic = `ldrp sr, V${x.toString(16)}`; break;
          case 0x85: mnemonic = `ldr vr, V${x.toString(16)}`; break;
          default: mnemonic = `F_${nn.toString(16)} V${x.toString(16)}`;
        }
        break;
      default: mnemonic = `??? ${op.toString(16).toUpperCase()}`;
    }
    return { mnemonic, x, y, nn, nnn, n, op };
  }

  executeInstruction() {
    if (this.pc >= 4096) return;
    const hi = this.memory[this.pc];
    const lo = this.memory[this.pc + 1];
    if (hi === undefined || lo === undefined) return;
    const op = (hi << 8) | lo;
    const decoded = this.decodeInstr(op);

    let skip = false;
    const x = decoded.x, y = decoded.y, nn = decoded.nn, nnn = decoded.nnn, n = decoded.n;

    switch(op & 0xF000) {
      case 0x0000:
        if (op === 0xE0E0) { this.display.fill(0); }
        else if (op === 0xEEEE) { this.pc = this.popStack(); skip = true; }
        else { /* sys - ignore */ }
        break;
      case 0x1000: this.pc = nnn; skip = true; break;
      case 0x2000: this.pushStack(this.pc); this.pc = nnn; skip = true; break;
      case 0x3000: if (this.V[x] === nn) { this.pc += 2; skip = true; } break;
      case 0x4000: if (this.V[x] !== nn) { this.pc += 2; skip = true; } break;
      case 0x5000: if (this.V[x] === this.V[y]) { this.pc += 2; skip = true; } break;
      case 0x6000: this.V[x] = nn; break;
      case 0x7000: this.V[x] = (this.V[x] + nn) & 0xFF; break;
      case 0x8000:
        switch(n) {
          case 0x0: this.V[x] = this.V[y]; break;
          case 0x1: this.V[x] |= this.V[y]; break;
          case 0x2: this.V[x] &= this.V[y]; break;
          case 0x3: this.V[x] ^= this.V[y]; break;
          case 0x4: { const old = this.V[x]; this.V[x] = (this.V[x] + this.V[y]) & 0xFF; this.V[0xF] = (this.V[x] < old) ? 1 : 0; } break;
          case 0x5: { const old = this.V[x]; this.V[x] = (this.V[x] - this.V[y]) & 0xFF; this.V[0xF] = (this.V[x] <= old) ? 1 : 0; } break;
          case 0x6: this.V[0xF] = this.V[x] & 1; this.V[x] >>= 1; break;
          case 0x7: { const old = this.V[x]; this.V[x] = (this.V[y] - this.V[x]) & 0xFF; this.V[0xF] = (this.V[x] <= old) ? 1 : 0; } break;
          case 0xE: this.V[0xF] = (this.V[x] >> 7) & 1; this.V[x] <<= 1; break;
        }
        break;
      case 0x9000: if (this.V[x] !== this.V[y]) { this.pc += 2; skip = true; } break;
      case 0xA000: this.I = nnn; break;
      case 0xB000: this.pc = (this.V[0] + nnn) & 0xFFF; skip = true; break;
      case 0xC000: this.V[x] = (Math.random() * 256) | 0 & nn; break;
      case 0xD000: {
        const vx = this.V[x], vy = this.V[y], height = n;
        this.V[0xF] = 0;
        for (let row = 0; row < height; row++) {
          if (vx + 64 > 64) break;
          const spriteByte = this.memory[this.I + row];
          const screenY = vy % 32;
          for (let col = 0; col < 8; col++) {
            if ((spriteByte & (0x80 >> col)) !== 0) {
              const sx = (vx + col) % 64;
              const sy = screenY + row;
              if (sy >= 32) continue;
              const idx = sy * 64 + sx;
              if (this.display[idx] === 1) this.V[0xF] = 1;
              this.display[idx] ^= 1;
            }
          }
        }
        break;
      }
      case 0xE000:
        if (nn === 0x9E) { if (this.keys[this.V[x]] !== 0) { this.pc += 2; skip = true; } }
        else if (nn === 0xA1) { if (this.keys[this.V[x]] === 0) { this.pc += 2; skip = true; } }
        break;
      case 0xF000:
        switch(nn) {
          case 0x07: this.V[x] = this.delayTimer; break;
          case 0x0A: {
            let keyFound = false;
            for (let i = 0; i < 16; i++) { if (this.keys[i]) { this.V[x] = i; keyFound = true; break; } }
            if (!keyFound) return; // wait for key press
            break;
          }
          case 0x15: this.delayTimer = this.V[x]; break;
          case 0x18: this.soundTimer = this.V[x]; break;
          case 0x1E: this.I = (this.I + this.V[x]) & 0xFFF; break;
          case 0x29: this.I = this.V[x] * 5; break;
          case 0x33: {
            const val = this.V[x];
            this.memory[this.I] = Math.floor(val / 100);
            this.memory[this.I + 1] = Math.floor((val % 100) / 10);
            this.memory[this.I + 2] = val % 10;
          } break;
          case 0x55: for (let i = 0; i <= x; i++) { this.memory[this.I + i] = this.V[i]; } break;
          case 0x65: for (let i = 0; i <= x; i++) { this.V[i] = this.memory[this.I + i]; } break;
          case 0x75: this.rpl = this.rpl || []; this.rpl[x] = this.V[x]; break;
          case 0x85: for (let i = 0; i <= x; i++) { this.V[i] = this.rpl ? this.rpl[i] : 0; } break;
        }
        break;
    }

    if (!skip) this.pc += 2;
    this.instructionsExecuted++;
    return decoded;
  }

  updateTimers() {
    if (this.delayTimer > 0) this.delayTimer--;
    if (this.soundTimer > 0) this.soundTimer--;
  }
}

// ===== UI SETUP =====
const canvas = document.getElementById('display');
const ctx = canvas.getContext('2d');
ctx.imageSmoothingEnabled = false;

