// ===== RENDERING =====
function renderDisplay() {
  // Create image data at 64x32 and scale up
  const imageData = ctx.createImageData(64, 32);
  for (let i = 0; i < chip8.display.length; i++) {
    const idx = i * 4;
    if (chip8.display[i]) {
      imageData.data[idx] = 0x00;
      imageData.data[idx + 1] = 0xFF;
      imageData.data[idx + 2] = 0xFF;
      imageData.data[idx + 3] = 0xFF;
    } else {
      imageData.data[idx] = 0x00;
      imageData.data[idx + 1] = 0x00;
      imageData.data[idx + 2] = 0x00;
      imageData.data[idx + 3] = 0xFF;
    }
  }

  // Draw scaled up
  const tempCanvas = document.createElement('canvas');
  tempCanvas.width = 64;
  tempCanvas.height = 32;
  const tempCtx = tempCanvas.getContext('2d');
  tempCtx.putImageData(imageData, 0, 0);

  ctx.clearRect(0, 0, 640, 320);
  ctx.drawImage(tempCanvas, 0, 0, 640, 320);
