    let bytes = '';
    for (let j = 0; j < 16; j++) {
      if (i + j < 256) {
        bytes += chip8.memory[i + j].toString(16).toUpperCase().padStart(2, '0') + ' ';
      }
    }
    html += `<span style="color:#888">${addr}:</span><span style="color:${i < 0x50 ? '#f90' : i >= 0x200 && i < 0x400 ? '#0f0' : '#aaa'}">${bytes}</span>\n`;
