function updateUI() {
  buildRegs();
  document.getElementById('idx-val').textContent = chip8.I.toString(16).toUpperCase().padStart(4, '0');
  document.getElementById('pc-val').textContent = chip8.pc.toString(16).toUpperCase().padStart(4, '0');
  buildStack();
  document.getElementById('delay-val').textContent = chip8.delayTimer;
  document.getElementById('sound-val').textContent = chip8.soundTimer;

  // Current instruction
  const hi = chip8.memory[chip8.pc];
  const lo = chip8.memory[chip8.pc + 1];
  if (hi !== undefined && lo !== undefined) {
    const op = (hi << 8) | lo;
    const decoded = chip8.decodeInstr(op);
    document.getElementById('current-instruction').textContent = 
      `PC: ${chip8.pc.toString(16).toUpperCase().padStart(4,'0')}h | ${op.toString(16).toUpperCase().padStart(4,'0')}h | ${decoded.mnemonic}`;
  } else {
    document.getElementById('current-instruction').textContent = `PC: ${chip8.pc.toString(16).toUpperCase().padStart(4,'0')}h | Out of bounds`;
  }

  buildMemory();
