// ===== CONTROLS =====
let running = false;
let animFrameId = null;
const speedSlider = document.getElementById('speed-slider');
const speedDisplay = document.getElementById('speed-display');
const statusBar = document.getElementById('status-bar');

speedSlider.addEventListener('input', () => {
  speedDisplay.textContent = speedSlider.value;
});

document.getElementById('btn-run').addEventListener('click', () => {
  if (!running) {
    running = true;
    statusBar.textContent = 'Running';
    document.getElementById('btn-run').classList.add('active');
    document.getElementById('btn-pause').classList.remove('active');
    gameLoop();
  }
});

document.getElementById('btn-pause').addEventListener('click', () => {
  running = false;
  if (animFrameId) cancelAnimationFrame(animFrameId);
  statusBar.textContent = 'Paused';
  document.getElementById('btn-pause').classList.add('active');
  document.getElementById('btn-run').classList.remove('active');
});

document.getElementById('btn-step').addEventListener('click', () => {
  if (running) return; // Can't step while running
  const decoded = chip8.executeInstruction();
  renderDisplay();
  updateUI();
});

document.getElementById('btn-reset').addEventListener('click', () => {
  running = false;
  if (animFrameId) cancelAnimationFrame(animFrameId);
  loadDemo();
  statusBar.textContent = 'Paused';
  document.getElementById('btn-run').classList.remove('active');
  document.getElementById('btn-pause').classList.remove('active');
});

// ROM file loader
document.getElementById('rom-file').addEventListener('change', (e) => {
  const file = e.target.files[0];
  if (!file) return;
  const reader = new FileReader();
  reader.onload = (ev) => {
    const data = new Uint8Array(ev.target.result);
    chip8.reset();
    chip8.loadROM(data);
    demoLoaded = false;
    statusBar.textContent = 'Paused';
    updateUI();
    renderDisplay();
  };
  reader.readAsArrayBuffer(file);
});

// ===== GAME LOOP =====
function gameLoop() {
  if (!running) return;

  const ipf = parseInt(speedSlider.value);
  // Execute instructions in batches
  for (let i = 0; i < ipf; i++) {
    chip8.executeInstruction();
  }

  // Update timers at 60Hz (every ~16.67ms)
  chip8.updateTimers();

  renderDisplay();
  updateUI();

  animFrameId = requestAnimationFrame(gameLoop);
}

// ===== INIT =====
loadDemo();
updateUI();
renderDisplay();
